import math


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("finite number required")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError("finite number required")
    return value


def cubic_score(x):
    x = _number(x)
    return 2 * x ** 3 + 4 * x + 7


def _vector3(value):
    try:
        items = tuple(value)
    except TypeError as exc:
        raise ValueError("vector must be iterable") from exc
    if len(items) != 3:
        raise ValueError("vector must have length 3")
    return tuple(_number(item) for item in items)


def build_report(a, b, left, right, angle):
    a = _number(a)
    b = _number(b)
    angle = _number(angle)
    if b == 0:
        raise ValueError("b must be nonzero")
    left = _vector3(left)
    right = _vector3(right)
    return {
        "true_quotient": a / b,
        "floor_quotient": math.floor(a / b),
        "remainder": a % b,
        "dot_product": sum(x * y for x, y in zip(left, right)),
        "sine": math.sin(angle),
        "cosine": math.cos(angle),
        "tangent": math.tan(angle),
    }


def verify_scores(values, expected):
    try:
        values = tuple(values)
        expected = tuple(expected)
    except TypeError as exc:
        raise ValueError("values and expected must be iterable") from exc
    if len(values) != len(expected):
        raise ValueError("lengths must match")
    checked_expected = tuple(_number(item) for item in expected)
    return [cubic_score(value) == target for value, target in zip(values, checked_expected)]

